// ASP.NET Core Identity's PasswordHasher does all of this (PBKDF2, salt, versioned format):
var hasher = new PasswordHasher<User>();
user.PasswordHash = hasher.HashPassword(user, password);

var result = hasher.VerifyHashedPassword(user, user.PasswordHash, attempt);
if (result == PasswordVerificationResult.SuccessRehashNeeded)
    user.PasswordHash = hasher.HashPassword(user, attempt); // upgrade to the current cost
